package com.muxigame.city;

import java.util.*;
import net.minecraft.server.MinecraftServer;

/** Finite two-way route, planned from local observations; arrival prices can still make it fail. */
public final class CityRoute {
 private static CityTrade.State priceState;private static long priceTick=Long.MIN_VALUE;private static final Map<UUID,int[]> meatQuotes=new HashMap<>();
 static void pricesChanged(){meatQuotes.clear();}
 static int buyMeat(MinecraftServer s,RuralRules.Family home,int wanted,long budget,boolean canCook){var t=CityTrade.get(s);var d=RuralSettlement.get(s);var stores=d.stocks(home.id);var goods=new ArrayList<Integer>();for(int g=canCook?0:5;g<10;g++)goods.add(g);goods.sort(Comparator.comparingInt(g->meatQuote(s,home.city,g)));int done=0;for(int g:goods)for(var seller:t.sellers(home.city,0)){int q=meatQuote(s,home.city,g);int n=(int)Math.min(Math.min(wanted-done,seller.meatListed[g].count),Math.min(RuralRules.capacity(stores),Math.min(budget,t.familyMoney(s,home))/q));if(n<=0)continue;long cost=seller.meatListed[g].cents*n/seller.meatListed[g].count;if(!t.familyPay(s,home,seller.account,n*(long)q))continue;seller.meatListed[g].take(n);pricesChanged();FoodMoves.add(stores,g+2,n,seller.meatListed[g].removedAge.age());seller.sales+=n*(long)q;t.profit(s,seller,n*q,cost);budget-=n*(long)q;done+=n;if(done>=wanted)return done;}return done;}
 static void emergency(MinecraftServer s,RuralRules.Family home){var d=RuralSettlement.get(s);var stores=d.stocks(home.id);boolean cook=FamilyLivelihood.processor(s,home);int food=RuralRules.count(stores,true)+stores.stream().mapToInt(v->Arrays.stream(v.cooked).sum()).sum();if(cook)food+=RuralRules.count(stores,false)+stores.stream().mapToInt(v->Arrays.stream(v.raw).sum()).sum();buyMeat(s,home,Math.max(0,RuralRules.demand(home,d.state.people)*2-food),CityTrade.get(s).familyMoney(s,home),cook);if(cook)FamilyLivelihood.cook(s,home);}
 static UUID village(CityTrade t,UUID city){var town=t.state.towns.get(city);return town.partner==null?(Objects.equals(city,t.state.run.city)?t.state.run.village:null):town.partner;}
 static int meatQuote(MinecraftServer s,UUID city,int good){var t=CityTrade.get(s);long now=RuralSettlement.get(s).state.simulationTicks;if(priceState!=t.state||priceTick!=now){priceState=t.state;priceTick=now;meatQuotes.clear();}int[] quotes=meatQuotes.get(city);if(quotes==null){quotes=new int[10];for(var b:t.state.businesses.values())if(b.city.equals(city))for(int g=0;g<10;g++)quotes[g]+=b.meatListed[g].count;int target=Math.max(1,CityTrade.population(s,city)/10);for(int g=0;g<10;g++)quotes[g]=FoodMarketRules.retail((int)Math.round(RuralMarket.baseSell(g+2)*t.state.config.cityMultiplier),quotes[g],target);meatQuotes.put(city,quotes);}return quotes[good];}
 static void capital(MinecraftServer s,CityTrade.Business b,long required){var d=RuralSettlement.get(s);var t=CityTrade.get(s);var e=CityEconomy.get(s);var p=d.state.people.get(b.owner);if(p==null||p.dead)return;var f=d.state.families.get(p.family);long reserve=FamilyBudget.reserve(s,f);long n=Math.min(Math.max(0,required-e.balance(b.account)),Math.min(e.balance(CityEconomy.person(p.id)),Math.max(0,t.familyMoney(s,f)-reserve)));if(n>0)CityTrade.pay(s,CityEconomy.person(p.id),b.account,n,"OWNER_REINVESTMENT");}
 static int room(MinecraftServer s,CityTrade.Business b){return Math.max(0,1000-CityTrade.get(s).held(b)-Arrays.stream(b.cargo).mapToInt(l->l.count).sum()-meatHeld(b));}
 static int meatHeld(CityTrade.Business b){return Arrays.stream(b.meatListed).mapToInt(l->l.count).sum()+Arrays.stream(b.meatCargo).mapToInt(l->l.count).sum();}
 static int buyCityGrain(MinecraftServer s,CityTrade.Business b,int wanted){var t=CityTrade.get(s);int got=0;for(var seller:t.sellers(b.city,0)){if(seller==b)continue;int q=t.quote(s,b.city,0,RuralSettlement.get(s).state.simulationTicks),n=(int)Math.min(Math.min(Math.min(wanted-got,192-b.cargo[0].count),Math.min(room(s,b),seller.listed[0].count)),Math.max(0,CityEconomy.get(s).balance(b.account)-40)/q);if(n<=0)continue;if(!CityTrade.pay(s,b.account,seller.account,n*(long)q,"OUTBOUND_GRAIN"))continue;long cost=seller.listed[0].take(n);b.cargo[0].receive(n,n*q*100L,seller.listed[0].removedAge);b.purchases+=n*(long)q;seller.sales+=n*(long)q;t.profit(s,seller,n*q,cost);t.soldFrom(seller,0);got+=n;if(got>=wanted)break;}return got;}
 static int ruralBid(MinecraftServer s,UUID village){var t=CityTrade.get(s);int retail=t.quote(s,village,0,RuralSettlement.get(s).state.simulationTicks);return Math.max(1,Math.min(retail,Math.max((int)Math.round(retail*.8),CityTrade.headQuote(s,village,0,RuralMarket.baseBuy(0),t.stock(s,village,0))/10)));}
 static void exchange(MinecraftServer s,CityTrade.Business b,CityTrade.Business head){var d=RuralSettlement.get(s);var t=CityTrade.get(s);var e=CityEconomy.get(s);var hp=d.state.people.get(head.worker);var stocks=d.stocks(hp.family);int q=ruralBid(s,head.city),wanted=b.cargo[0].count;if(wanted==0)return;
  // Negotiate both deliveries at once: a full meat warehouse can buy grain and sell meat without imaginary slots.
  int free=RuralRules.capacity(stocks),need=Math.max(0,wanted-free),bought=0;long meatCost=0;int[] meat=new int[10];
  for(int g=0;g<10&&bought<need;g++){int price=RuralFoodAccess.retail(d,hp,g+2,stocks);if(meatQuote(s,b.city,g)*b.perception<price*2.25)continue;int n=Math.min(need-bought,RuralCooking.available(d,hp,g+2,stocks));n=Math.min(n,192-b.meatCargo[g].count);meat[g]=n;bought+=n;meatCost+=n*(long)price;}
  int grain=Math.min(wanted,free+bought);if(grain<=0)return;long revenue=grain*(long)q,net=revenue-meatCost;
  if(net>CityWorksFinance.spendable(s,head.account)||-net>e.balance(b.account))return;
  long grainCost=b.cargo[0].cents*grain/b.cargo[0].count;
  long taxable=(Math.max(0,revenue*100L-grainCost-b.expenseCents)+b.profitCents)/100;
  long tax=(t.state.taxTails.getOrDefault("profit:"+b.id,0)+taxable*15)/100;
  if(e.balance(b.account)+net<tax)return;
  if(net>=0){if(!CityTrade.pay(s,head.account,b.account,net,"ROUTE_NET_GRAIN_MEAT"))return;}else if(!CityTrade.pay(s,b.account,head.account,-net,"ROUTE_NET_GRAIN_MEAT"))return;
  for(int g=0;g<10;g++)if(meat[g]>0){int price=RuralFoodAccess.retail(d,hp,g+2,stocks);var portion=FoodMoves.remove(stocks,g+2,meat[g]);b.meatCargo[g].receive(meat[g],meat[g]*price*100L,portion);b.purchases+=meat[g]*(long)price;}
  long cost=b.cargo[0].take(grain);CityEconomy.require(FoodMoves.add(stocks,0,grain,b.cargo[0].removedAge.age())==grain,"Reverse route grain space checked before payment");b.sales+=revenue;b.sold[0]+=grain;t.profit(s,b,(int)revenue,cost);head.purchases+=revenue;t.state.reverseGrain+=grain;t.state.routeMeat+=bought;d.setDirty();
 }
 static void arriveHome(MinecraftServer s,CityTrade.Business b){var t=CityTrade.get(s);for(int g=0;g<4;g++)TradeRules.move(b.cargo[g],b.stock[g],b.cargo[g].count);for(int g=0;g<10;g++)TradeRules.move(b.meatCargo[g],b.meatListed[g],b.meatCargo[g].count);pricesChanged();b.phase=0;b.trips++;t.withdraw(s,b);}
 static void travel(MinecraftServer s,CityTrade.Business b,long now,long day){var t=CityTrade.get(s);var d=RuralSettlement.get(s);var e=CityEconomy.get(s);if(!b.kind.equals("procurement")||CityRiskLab.tradeBlocked(s,b.city)||!t.usable(s,b)||!WorkHours.active(s,CityData.get(s).require(b.city),b.worker))return;if(b.phase==2){if(now>=b.arrive)arriveHome(s,b);return;}UUID village=village(t,b.city);var head=t.liveHead(s,village);if(head==null){if(b.phase==1&&now>=b.arrive){b.phase=2;b.arrive=now+Math.round(t.state.config.travelTicks/FamilyLivelihood.workFactor(s,d.state.people.get(b.worker)));b.emptyTrips++;b.status="头人已不在，保留原货返程";}return;}var hp=d.state.people.get(head.worker);var stocks=d.stocks(hp.family);
  if(b.phase==0){if(b.departedDay==day||Math.floorMod(d.state.simulationDay,24000)>1200||t.held(b)+meatHeld(b)>=900)return;b.perception=1+(s.overworld().random.nextDouble()*2-1)*t.state.config.perceptionError;int cityQ=t.quote(s,b.city,0,now),ruralQ=t.quote(s,village,0,now);b.reverse=ruralBid(s,village)*b.perception>=cityQ*1.5&&t.stock(s,b.city,0)>0;
   b.planned=TradeRules.plan(t.stock(s,b.city,0),t.target(s,b.city,0),t.base(b.city,0),ruralQ,b.perception,Math.min(192-b.cargo[0].count,room(s,b)),100000,t.state.towns.get(b.city).prices[0].richSince<0?0:now-t.state.towns.get(b.city).prices[0].richSince);
   boolean goods=false;for(int g=2;g<4;g++)if(t.quote(s,village,g,now)*.95*b.perception>=t.quote(s,b.city,g,now)*1.25&&t.stock(s,b.city,g)>0)goods=true;
   boolean meat=false;for(int g=0;g<10;g++)if(RuralMarket.count(stocks,g+2)>0&&meatQuote(s,b.city,g)*b.perception>=RuralFoodAccess.retail(d,hp,g+2,stocks)*2.25)meat=true;
   if(!b.reverse&&b.planned==0&&!goods&&!meat){b.status="两地均无可见有利交易，待命";return;}capital(s,b,Math.min(616,40L+64L*(b.reverse?cityQ:ruralQ)));if(b.reverse)buyCityGrain(s,b,Math.min(192,TradeRules.capacity(b.cargo)));
   for(int g=2;g<4;g++)for(int cargoUnit=0;cargoUnit<8;cargoUnit++){int q=t.quote(s,b.city,g,now);if(t.quote(s,village,g,now)*.95*b.perception<q*1.25)continue;for(var seller:t.sellers(b.city,g))if(seller!=b&&room(s,b)>0&&seller.listed[g].count>0&&e.balance(b.account)>=q+40&&CityTrade.pay(s,b.account,seller.account,q,"OUTBOUND_GOODS")){long cost=seller.listed[g].take(1);b.cargo[g].add(1,q*100L);b.purchases+=q;seller.sales+=q;t.profit(s,seller,q,cost);t.soldFrom(seller,g);break;}}
   if(e.balance(b.account)<41&&Arrays.stream(b.cargo).allMatch(l->l.count==0))return;b.phase=1;b.arrive=now+Math.round(t.state.config.travelTicks/FamilyLivelihood.workFactor(s,d.state.people.get(b.worker)));b.departedDay=day;b.status=b.reverse?"向农村运输实际余粮":"前往农村双向交易";
  }else if(b.phase==1&&now>=b.arrive){exchange(s,b,head);int price=t.quote(s,village,0,now),protect=RuralMarket.reserve(d,d.state.families.values().stream().filter(f->f.city.equals(village)).toList(),d.state.families.get(hp.family)),available=Math.max(0,RuralRules.count(stocks,false)-Math.max(0,protect-RuralRules.count(stocks,true)));int n=(int)Math.min(Math.min(b.reverse?0:b.planned,available),Math.min(room(s,b),Math.max(0,e.balance(b.account)-40)/price));if(n>0&&CityTrade.pay(s,b.account,head.account,n*(long)price,"VILLAGE_GRAIN_PURCHASE")){var portion=FoodMoves.remove(stocks,0,n);b.cargo[0].receive(n,n*price*100L,portion);b.purchases+=n*(long)price;t.state.run.grainTrades+=n;}if(!b.reverse&&b.planned>n)RuralStalls.freight(s,b,village,b.planned-n);
   for(int g=2;g<4;g++)for(int cargoUnit=0;cargoUnit<8;cargoUnit++){int q=Math.max(1,(int)Math.floor(t.quote(s,village,g,now)*.95+.5));if(b.cargo[g].count>0&&q>=b.cargo[g].unit()&&CityWorksFinance.spendable(s,head.account)>=q&&t.held(head)<1000&&CityTrade.pay(s,head.account,b.account,q,"VILLAGE_CONSUMER_IMPORT")){long cost=b.cargo[g].take(1);head.stock[g].add(1,q*100L);b.sales+=q;head.purchases+=q;t.profit(s,b,q,cost);}}
   for(int g=0;g<10;g++){int q=RuralFoodAccess.retail(d,hp,g+2,stocks);if(meatQuote(s,b.city,g)*b.perception<q*2.25)continue;int room=Math.min(192-b.meatCargo[g].count,Math.max(0,1000-t.held(b)-meatHeld(b)));int take=(int)Math.min(Math.min(room,RuralCooking.available(d,hp,g+2,stocks)),Math.max(0,e.balance(b.account)-40)/q);if(take>0&&CityTrade.pay(s,b.account,head.account,take*(long)q,"CITY_MEAT_IMPORT")){var portion=FoodMoves.remove(stocks,g+2,take);b.meatCargo[g].receive(take,take*q*100L,portion);b.purchases+=take*(long)q;t.state.routeMeat+=take;}}
   b.phase=2;b.arrive=now+Math.round(t.state.config.travelTicks/FamilyLivelihood.workFactor(s,d.state.people.get(b.worker)));b.status="回城，按到达时市场价格出售";
  }else if(b.phase==2&&now>=b.arrive){arriveHome(s,b);}
 }
}






